void main(List<String> args) {
  if (args.length != 1) {
    stderr.writeln(
      'usage: dart run tool/gen_schema.dart `<GameDataList.Product.110.byml>`',
    );
    exitCode = 64;
    return;
  }
  try {
    final bytes = File(args.single).readAsBytesSync();
    final output = _generate(bytes);
    stdout.writeln(jsonEncode(output));
  } on Object catch (error) {
    stderr.writeln('gen_schema: $error');
    exitCode = 1;
  }
}

Map<String, Object?> _generate(Uint8List bytes) {
  final byml = _Byml(bytes);
  final root = _map(byml.root, 'root');
  final data = _map(root['Data'], 'Data');
  final meta = _map(root['MetaData'], 'MetaData');
  final names = _parseNames();
  final order = _decodeRecordOrder();

  final typeOf = <int, String>{};
  final entryOf = <int, Map<String, Object?>>{};
  var bymlEntries = 0;
  for (final typeEntry in data.entries) {
    final list = typeEntry.value;
    if (list is! List) {
      continue;
    }
    for (var i = 0; i < list.length; i++) {
      final entry = _map(list[i], 'Data.${typeEntry.key}[$i]');
      final hash = _int(entry['Hash'], 'Data.${typeEntry.key}[$i].Hash');
      if (typeOf.containsKey(hash)) {
        throw StateError('Duplicate byml hash ${hashHex(hash)}');
      }
      typeOf[hash] = typeEntry.key;
      entryOf[hash] = entry;
      bymlEntries++;
    }
  }

  final entriesByType = <String, List<Map<String, Object?>>>{};
  for (final (_, typeName) in _sectionTypes) {
    final list = data[typeName];
    if (list is! List) {
      throw StateError('Missing byml type $typeName');
    }
    entriesByType[typeName] = <Map<String, Object?>>[
      for (final raw in list)
        if (_int(
              _map(raw, typeName)['SaveFileIndex'],
              '$typeName.SaveFileIndex',
            ) ==
            0)
          _map(raw, typeName),
    ];
  }

  final diskHashes = <int>{};
  final recordIndex = <int, int>{};
  var orderCursor = 0;
  var raw = 0;
  final sectionRanges = <int, (int, int, int)>{};
  for (var typeId = 1; typeId <= 32; typeId++) {
    final typeName = _typeNameFor(typeId);
    if (typeName == null) {
      raw += 1; // sentinel-only section
      continue;
    }
    final entries = entriesByType[typeName]!;
    final start = raw;
    final end = raw + entries.length - 1;
    sectionRanges[typeId] = (start, end, end + 1);
    final expected = <int>{
      for (final entry in entries) _int(entry['Hash'], '$typeName.Hash'),
    };
    for (var i = 0; i < entries.length; i++) {
      final hash = order[orderCursor++];
      if (!expected.contains(hash)) {
        throw StateError(
          'Record order mismatch at ${hashHex(hash)} for $typeName',
        );
      }
      recordIndex[hash] = start + i;
      diskHashes.add(hash);
    }
    raw += entries.length + 1; // fields plus {0, typeId} sentinel
  }
  if (orderCursor != order.length) {
    throw StateError(
      'Record order has ${order.length - orderCursor} extra keys',
    );
  }
  if (raw != 11957) {
    throw StateError('Raw record count $raw, expected 11957 before footer');
  }

  final expectedDiskHashes = <int>{
    for (final typeName in entriesByType.keys)
      for (final entry in entriesByType[typeName]!)
        _int(entry['Hash'], '$typeName.Hash'),
  };
  if (diskHashes.length != expectedDiskHashes.length ||
      !diskHashes.containsAll(expectedDiskHashes)) {
    throw StateError(
      'Embedded record order does not match the byml saveFileIndex=0 set',
    );
  }

  final enumTables = _buildEnumTables(data, names);
  final fields = <Map<String, Object?>>[];
  for (final (typeId, typeName) in _sectionTypes) {
    for (final entry in entriesByType[typeName]!) {
      final hash = _int(entry['Hash'], '$typeName.Hash');
      fields.add(
        _field(
          id: 0,
          hash: hash,
          typeName: typeName,
          section: typeId,
          entry: entry,
          name: names[hash],
          enumKey: enumTables.keyByHash[hash],
          enumMembers: enumTables.membersByKey[enumTables.keyByHash[hash]],
          presentOnDisk: true,
          recordIndex: recordIndex[hash],
          saveFileIndex: 0,
          notes: null,
        ),
      );
    }
  }
  fields.sort((a, b) => (a['hash']! as int).compareTo(b['hash']! as int));
  for (var i = 0; i < fields.length; i++) {
    fields[i]['id'] = i;
  }

  final declared = <Map<String, Object?>>[];
  for (final typeEntry in data.entries) {
    final typeName = typeEntry.key;
    if (typeName == 'Struct' ||
        typeName == 'BoolExp' ||
        typeName == 'Bool64bitKey') {
      continue;
    }
    if (_SaveTypes.fromWireName(typeName) == null) {
      continue;
    }
    final list = typeEntry.value;
    if (list is! List) {
      continue;
    }
    for (final rawEntry in list) {
      final entry = _map(rawEntry, 'Data.$typeName');
      final saveFileIndex = _int(
        entry['SaveFileIndex'],
        '$typeName.SaveFileIndex',
      );
      if (saveFileIndex != -1) {
        continue;
      }
      final hash = _int(entry['Hash'], '$typeName.Hash');
      declared.add(
        _field(
          id: 0,
          hash: hash,
          typeName: typeName,
          section: _sectionIdFor(typeName),
          entry: entry,
          name: names[hash],
          enumKey: enumTables.keyByHash[hash],
          enumMembers: enumTables.membersByKey[enumTables.keyByHash[hash]],
          presentOnDisk: false,
          recordIndex: null,
          saveFileIndex: -1,
          notes: 'SaveFileIndex -1; runtime-only declaration',
        ),
      );
    }
  }
  declared.sort((a, b) => (a['hash']! as int).compareTo(b['hash']! as int));
  for (var i = 0; i < declared.length; i++) {
    declared[i]['id'] = i;
  }

  final absent = <Map<String, Object?>>[];
  final bool64 = data['Bool64bitKey'];
  if (bool64 is! List) {
    throw StateError('Missing Data.Bool64bitKey');
  }
  for (var i = 0; i < bool64.length; i++) {
    final entry = _map(bool64[i], 'Bool64bitKey[$i]');
    absent.add(<String, Object?>{
      'id': 0,
      'name': null,
      'hash64': _int(entry['Hash'], 'Bool64bitKey[$i].Hash'),
      'type': 'Bool64bitKey',
      'section': null,
      'default': null,
      'arrayLen': null,
      'enumValues': null,
      'defaultLabel': null,
      'saveFileIndex': 0,
      'presentOnDisk': false,
      'verified': false,
      'recordIndex': null,
      'nameSource': null,
      'notes': 'Bool64bitKey; declared but not serialized into progress.sav',
    });
  }
  absent.sort((a, b) => (a['hash64']! as int).compareTo(b['hash64']! as int));
  for (var i = 0; i < absent.length; i++) {
    absent[i]['id'] = i;
  }

  final sections = <Map<String, Object?>>[];
  for (final (typeId, typeName) in _sectionTypes) {
    final range = sectionRanges[typeId]!;
    sections.add(<String, Object?>{
      'typeId': typeId,
      'typeName': typeName,
      'count': entriesByType[typeName]!.length,
      'sentinelValue': typeId,
      'recordStart': range.$1,
      'recordEnd': range.$2,
      'sentinelRecordIndex': range.$3,
    });
  }

  final unnamedByType = <String, int>{};
  var namedCount = 0;
  for (final field in fields) {
    if (field['name'] == null) {
      final type = field['type']! as String;
      unnamedByType[type] = (unnamedByType[type] ?? 0) + 1;
    } else {
      namedCount++;
    }
  }
  final unnamedSorted = <String, int>{};
  for (final key in unnamedByType.keys.toList()..sort()) {
    unnamedSorted[key] = unnamedByType[key]!;
  }

  final enumKeys = enumTables.membersByKey.keys.toList()..sort();
  final enums = <String, Object?>{
    for (final key in enumKeys)
      key: <Map<String, Object?>>[
        for (final member in enumTables.membersByKey[key]!)
          <String, Object?>{'name': member.name, 'hash': member.hash},
      ],
  };

  var enumMemberUses = 0;
  for (final typeName in <String>['Enum', 'EnumArray']) {
    final list = data[typeName];
    if (list is! List) {
      continue;
    }
    for (final rawEntry in list) {
      final entry = _map(rawEntry, 'Data.$typeName');
      final rawValues = entry['RawValues'];
      if (rawValues is List) {
        enumMemberUses += rawValues.length;
      }
    }
  }

  final saveDirectory = meta['SaveDirectory'];
  final saveTypeHash = meta['SaveTypeHash'];
  final provenance = <String, Object?>{
    'source': 'GameDataList.Product.110',
    'extractedBy': 'tool/gen_schema.dart',
    'note': 'names/types/defaults only; no game assets',
    'bymlFormatVersion': byml.formatVersion,
    'bymlEndian': byml.littleEndian ? 'little' : 'big',
    'saveFileIndexMap': saveDirectory is List
        ? saveDirectory.cast<Object?>()
        : <Object?>[],
    'saveTypeHashes': saveTypeHash is List
        ? saveTypeHash.cast<Object?>()
        : <Object?>[],
    'nameTable': 'hash<TAB>source<TAB>name; every line Murmur3-verified',
  };

  final counts = <String, int>{
    'bymlEntries': bymlEntries,
    'onDiskFields': fields.length,
    'absentBool64bitKey': absent.length,
    'declaredNotSaved': declared.length,
    'namedFields': namedCount,
    'unnamedFields': fields.length - namedCount,
    'enumTables': enumKeys.length,
    'enumMembers': enumKeys.fold<int>(
      0,
      (sum, key) => sum + enumTables.membersByKey[key]!.length,
    ),
    'enumMemberUses': enumMemberUses,
    'sections': sections.length,
    'emptySections': _emptySectionIds.length,
  };

  return <String, Object?>{
    'schemaRevision': _schemaRevision,
    'schemaRevisionHex': revisionHex(_schemaRevision),
    'game': _game,
    'provenance': provenance,
    'counts': counts,
    'sections': sections,
    'emptySectionIds': _emptySectionIds,
    'fields': fields,
    'absentFields': absent,
    'declaredNotSaved': declared,
    'enums': enums,
    'unresolved': <Map<String, Object?>>[
      <String, Object?>{
        'reason': 'field_name_unresolved',
        'count': fields.length - namedCount,
        'typeCounts': unnamedSorted,
        'note':
            'The byml stores only Murmur3 hashes. These on-disk fields are '
            'hash-verified but no name preimage was recovered from the '
            'available string tables or host code.',
      },
    ],
  };
}

Map<String, Object?> _field({
  required int id,
  required int hash,
  required String typeName,
  required int? section,
  required Map<String, Object?> entry,
  required _Name? name,
  required String? enumKey,
  required List<_EnumMember>? enumMembers,
  required bool presentOnDisk,
  required int? recordIndex,
  required int saveFileIndex,
  required String? notes,
}) {
  final defaultValue = _convertDefault(typeName, entry['DefaultValue']);
  String? defaultLabel;
  if (enumMembers != null && defaultValue is int) {
    for (final member in enumMembers) {
      if (member.hash == defaultValue) {
        defaultLabel = member.name;
        break;
      }
    }
  }
  return <String, Object?>{
    'id': id,
    'name': name?.name,
    'hash': hash,
    'type': typeName,
    'section': section,
    'default': defaultValue,
    'arrayLen': _arrayLen(typeName, entry),
    'enumValues': enumKey,
    'defaultLabel': defaultLabel,
    'saveFileIndex': saveFileIndex,
    'presentOnDisk': presentOnDisk,
    'verified': true,
    'recordIndex': recordIndex,
    'nameSource': name?.source,
    'notes': notes,
  };
}

int? _sectionIdFor(String typeName) {
  for (final (typeId, name) in _sectionTypes) {
    if (name == typeName) {
      return typeId;
    }
  }
  return null;
}

String? _typeNameFor(int typeId) {
  for (final (id, name) in _sectionTypes) {
    if (id == typeId) {
      return name;
    }
  }
  return null;
}

Object? _convertDefault(String typeName, Object? value) {
  if (value == null) {
    return null;
  }
  if (typeName == 'Vector3') {
    final map = _map(value, 'Vector3 default');
    return <String, Object?>{
      'x': _num(map['x'], 'Vector3.x').toDouble(),
      'y': _num(map['y'], 'Vector3.y').toDouble(),
      'z': _num(map['z'], 'Vector3.z').toDouble(),
    };
  }
  if (typeName == 'Float' || typeName == 'FloatArray') {
    return _num(value, 'Float default').toDouble();
  }
  return value;
}

int? _arrayLen(String typeName, Map<String, Object?> entry) {
  if (typeName == 'Binary') {
    return null;
  }
  for (final key in <String>['TotalSize', 'ArraySize', 'OriginalSize']) {
    final value = entry[key];
    if (value != null) {
      return _int(value, '$typeName.$key');
    }
  }
  return null;
}

final class _EnumTables {
  _EnumTables(this.keyByHash, this.membersByKey);

  final Map<int, String> keyByHash;
  final Map<String, List<_EnumMember>> membersByKey;
}

final class _EnumMember {
  const _EnumMember(this.name, this.hash);

  final String name;
  final int hash;
}

_EnumTables _buildEnumTables(Map<String, Object?> data, Map<int, _Name> names) {
  final bySignature = <String, List<Map<String, Object?>>>{};
  for (final typeName in <String>['Enum', 'EnumArray']) {
    final list = data[typeName];
    if (list is! List) {
      continue;
    }
    for (final rawEntry in list) {
      final entry = _map(rawEntry, 'Data.$typeName');
      final rawValues = _list(entry['RawValues'], '$typeName.RawValues');
      final signature = rawValues
          .map((value) => value.toString())
          .join('\u0000');
      bySignature
          .putIfAbsent(signature, () => <Map<String, Object?>>[])
          .add(entry);
    }
  }

  final keyByHash = <int, String>{};
  final membersByKey = <String, List<_EnumMember>>{};
  final usedKeys = <String>{};
  for (final entries in bySignature.values) {
    final named = <String>[
      for (final entry in entries)
        if (names[_int(entry['Hash'], 'Enum.Hash')] != null)
          names[_int(entry['Hash'], 'Enum.Hash')]!.name,
    ]..sort();
    final minHash = entries
        .map((entry) => _int(entry['Hash'], 'Enum.Hash'))
        .reduce((a, b) => a < b ? a : b);
    var key = named.isEmpty
        ? 'enum_${hashHex(minHash).substring(2)}'
        : named.first;
    var suffix = 2;
    while (!usedKeys.add(key)) {
      key =
          '${named.isEmpty ? 'enum_${hashHex(minHash).substring(2)}' : named.first}_$suffix';
      suffix++;
    }
    final rawValues = _list(entries.first['RawValues'], 'Enum.RawValues');
    final values = _list(entries.first['Values'], 'Enum.Values');
    if (rawValues.length != values.length) {
      throw StateError('Enum RawValues/Values length mismatch for $key');
    }
    final members = <_EnumMember>[];
    for (var i = 0; i < rawValues.length; i++) {
      final memberName = _string(rawValues[i], '$key.RawValues[$i]');
      final memberHash = _int(values[i], '$key.Values[$i]');
      if (murmur3X86_32(memberName) != memberHash) {
        throw StateError('Enum member $key.$memberName hash mismatch');
      }
      members.add(_EnumMember(memberName, memberHash));
    }
    membersByKey[key] = members;
    for (final entry in entries) {
      keyByHash[_int(entry['Hash'], 'Enum.Hash')] = key;
    }
  }
  return _EnumTables(keyByHash, membersByKey);
}

Map<int, _Name> _parseNames() {
  final result = <int, _Name>{};
  for (final line in _nameTable.split('\n')) {
    if (line.isEmpty) {
      continue;
    }
    final first = line.indexOf('\t');
    final second = line.indexOf('\t', first + 1);
    if (first != 8 || second < 0) {
      throw StateError('Bad name table line: $line');
    }
    final hash = int.parse(line.substring(0, first), radix: 16);
    final source = line.substring(first + 1, second);
    final name = line.substring(second + 1);
    if (murmur3X86_32(name) != hash) {
      throw StateError('Name table hash mismatch for $name');
    }
    result[hash] = _Name(name, source);
  }
  return result;
}

final class _Name {
  const _Name(this.name, this.source);

  final String name;
  final String source;
}

List<int> _decodeRecordOrder() {
  final bytes = base64Decode(_recordOrderBase64);
  final data = ByteData.sublistView(bytes);
  return <int>[
    for (var i = 0; i < bytes.length; i += 4) data.getUint32(i, Endian.little),
  ];
}

/// Minimal BYML reader for v4-v7, big- or little-endian.
final class _Byml {
  _Byml(this.bytes) : data = ByteData.sublistView(bytes) {
    if (bytes.length < 16) {
      throw const FormatException('BYML too short');
    }
    final magic = String.fromCharCodes(bytes.sublist(0, 2));
    if (magic != 'BY' && magic != 'YB') {
      throw FormatException('Not a BYML file (magic $magic)');
    }
    littleEndian = magic == 'YB';
    formatVersion = _u16(2);
    _keyTableOffset = _u32(4);
    _stringTableOffset = _u32(8);
    _rootOffset = _u32(12);
    _keys = _readStrings(_keyTableOffset);
    _strings = _readStrings(_stringTableOffset);
    root = _node(_rootOffset);
  }

  final Uint8List bytes;
  final ByteData data;
  late final bool littleEndian;
  late final int formatVersion;
  late final int _keyTableOffset;
  late final int _stringTableOffset;
  late final int _rootOffset;
  late final List<String> _keys;
  late final List<String> _strings;
  late final Object? root;

  int _u16(int offset) => littleEndian
      ? data.getUint16(offset, Endian.little)
      : data.getUint16(offset, Endian.big);

  int _u24(int offset) {
    if (littleEndian) {
      return bytes[offset] |
          (bytes[offset + 1] << 8) |
          (bytes[offset + 2] << 16);
    }
    return (bytes[offset] << 16) | (bytes[offset + 1] << 8) | bytes[offset + 2];
  }

  int _u32(int offset) => littleEndian
      ? data.getUint32(offset, Endian.little)
      : data.getUint32(offset, Endian.big);

  int _i32(int offset) => littleEndian
      ? data.getInt32(offset, Endian.little)
      : data.getInt32(offset, Endian.big);

  double _f32(int offset) => littleEndian
      ? data.getFloat32(offset, Endian.little)
      : data.getFloat32(offset, Endian.big);

  int _i64(int offset) => littleEndian
      ? data.getInt64(offset, Endian.little)
      : data.getInt64(offset, Endian.big);

  int _u64(int offset) => littleEndian
      ? data.getUint64(offset, Endian.little)
      : data.getUint64(offset, Endian.big);

  double _f64(int offset) => littleEndian
      ? data.getFloat64(offset, Endian.little)
      : data.getFloat64(offset, Endian.big);

  List<String> _readStrings(int base) {
    if (bytes[base] != 0xC2) {
      throw FormatException('Bad string table at 0x${base.toRadixString(16)}');
    }
    final count = _u24(base + 1);
    final result = <String>[];
    for (var i = 0; i < count; i++) {
      final relative = _u32(base + 4 + 4 * i);
      if (relative == 0) {
        result.add('');
        continue;
      }
      final start = base + relative;
      var end = start;
      while (end < bytes.length && bytes[end] != 0) {
        end++;
      }
      result.add(utf8.decode(bytes.sublist(start, end), allowMalformed: true));
    }
    return result;
  }

  Object? _node(int offset) {
    if (offset <= 0 || offset >= bytes.length) {
      throw FormatException('BYML node offset out of range: $offset');
    }
    final type = bytes[offset];
    if (type == 0xA0) {
      return _strings[_u32(offset + 1)];
    }
    if (type == 0xA1) {
      final at = _u32(offset + 1);
      final length = _u32(at);
      return Uint8List.fromList(bytes.sublist(at + 4, at + 4 + length));
    }
    if (type == 0xC0 || type == 0xC8) {
      final count = _u24(offset + 1);
      final typesAt = offset + 4;
      final valuesAt = typesAt + ((count + 3) & ~3);
      return <Object?>[
        for (var i = 0; i < count; i++)
          _value(bytes[typesAt + i], valuesAt + 4 * i),
      ];
    }
    if (type == 0xC1 || type == 0xC4) {
      final count = _u24(offset + 1);
      final result = <String, Object?>{};
      for (var i = 0; i < count; i++) {
        final at = offset + 4 + 8 * i;
        final key = _keys[_u24(at)];
        result[key] = _value(bytes[at + 3], at + 4);
      }
      return result;
    }
    if (type >= 0x20 && type <= 0x3F) {
      final count = _u24(offset + 1);
      final size = (type & 0xF) == 0 ? 1 : type & 0xF;
      final result = <int, Object?>{};
      for (var i = 0; i < count; i++) {
        final at = offset + 4 + (size + 1) * 4 * i;
        var hash = 0;
        for (var b = 0; b < size * 4; b++) {
          final byte = bytes[at + b];
          hash = littleEndian
              ? (hash | (byte << (8 * b)))
              : ((hash << 8) | byte);
        }
        result[hash] = _value(bytes[at + size * 4], at + size * 4 + 1);
      }
      return result;
    }
    return _value(type, offset + 1);
  }

  Object? _value(int type, int offset) {
    if (type == 0xA0) {
      return _strings[_u32(offset)];
    }
    if (type == 0xA1) {
      final at = _u32(offset);
      final length = _u32(at);
      return Uint8List.fromList(bytes.sublist(at + 4, at + 4 + length));
    }
    if (type == 0xC0 ||
        type == 0xC8 ||
        type == 0xC1 ||
        type == 0xC4 ||
        (type >= 0x20 && type <= 0x3F)) {
      return _node(_u32(offset));
    }
    if (type == 0xD0) {
      return _u32(offset) != 0;
    }
    if (type == 0xD1) {
      return _i32(offset);
    }
    if (type == 0xD2) {
      return _f32(offset);
    }
    if (type == 0xD3) {
      return _u32(offset);
    }
    if (type == 0xD4) {
      return _i64(_u32(offset));
    }
    if (type == 0xD5) {
      return _u64(_u32(offset));
    }
    if (type == 0xD6) {
      return _f64(_u32(offset));
    }
    if (type == 0xFF || type == 0x00) {
      return null;
    }
    throw FormatException('Unknown BYML type 0x${type.toRadixString(16)}');
  }
}

/// Local mirror of the loader's wire-name check, so the generator does not
/// depend on Flutter or on the JSON model.
abstract final class _SaveTypes {
  static const Set<String> names = <String>{
    'Bool',
    'BoolArray',
    'Int',
    'IntArray',
    'Float',
    'FloatArray',
    'Enum',
    'EnumArray',
    'Vector3',
    'String16',
    'String32',
    'String64',
    'String64Array',
    'Binary',
    'BinaryArray',
    'UInt',
    'UIntArray',
    'Int64',
    'UInt64',
    'UInt64Array',
    'WString16',
    'WString16Array',
    'Bool64bitKey',
  };

  static String? fromWireName(String name) =>
      names.contains(name) ? name : null;
}

Map<String, Object?> _map(Object? value, String context) {
  if (value is Map<String, Object?>) {
    return value;
  }
  if (value is Map) {
    return value.map(
      (key, entry) => MapEntry(key.toString(), entry as Object?),
    );
  }
  throw FormatException('$context must be an object');
}

List<Object?> _list(Object? value, String context) {
  if (value is List<Object?>) {
    return value;
  }
  if (value is List) {
    return value.cast<Object?>();
  }
  throw FormatException('$context must be a list');
}

int _int(Object? value, String context) {
  if (value is int) {
    return value;
  }
  if (value is num && value == value.roundToDouble()) {
    return value.toInt();
  }
  throw FormatException('$context must be an integer');
}

num _num(Object? value, String context) {
  if (value is num) {
    return value;
  }
  throw FormatException('$context must be a number');
}

String _string(Object? value, String context) {
  if (value is String) {
    return value;
  }
  throw FormatException('$context must be a string');
}
